    <style>
        /* Base styles with Light/Dark Mode Support via CSS variables */

        :root {
            --bg-color: #000000;
            --text-color: #ffffff;
            --btn-bg: #ffffff;
            --btn-text: #000000;
            --btn-hover: #e0e0e0;
