        }


        body, html {
            margin: 0;
            padding: 0;
            width: 100%;
            height: 100%;
            overflow-x: hidden;
            background-color: var(--bg-color);
            color: var(--text-color);
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        /* Container that takes full height and flexes content */
        .hero-container {
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            height: 100vh;
            position: relative;
            text-align: center;
            padding: 1.5rem;
            box-sizing: border-box;
        }

        /* Video wrapper for responsive iframe */
        .video-background {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            z-index: -1;
            pointer-events: none;
            overflow: hidden;
            background-color: var(--bg-color);
        }

        /* The iframe needs to scale to cover the screen without letterboxing */
        .video-background iframe {
            position: absolute;
            top: 50%;
            left: 50%;
            width: 100vw;
            height: 56.25vw; /* 16:9 Aspect Ratio */
            min-height: 100vh;
            min-width: 177.77vh; /* 16:9 Aspect Ratio */
            transform: translate(-50%, -50%);
        }

        /* Overlay for readability */
        .overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: linear-gradient(to bottom, var(--overlay-start) 0%, var(--overlay-end) 100%);
            z-index: 0;
            transition: background 0.5s ease;
        }

        /* Content Layer above video and overlay */
        .content-layer {
            z-index: 10;
            position: relative;
            display: flex;
            flex-direction: column;
            align-items: center;
            width: 100%;
        }

        /* Progressive Logo Reveal Animation */
        .reveal-logo {
            opacity: 0;
            animation: fadeInLogo 2s ease-in-out forwards;
            animation-delay: 3s; /* Wait exactly 3 seconds to trigger */
            margin-bottom: 3rem;
        }

        @keyframes fadeInLogo {
            0% { opacity: 0; transform: scale(0.9); filter: blur(10px); }
            100% { opacity: 1; transform: scale(1); filter: blur(0px); }
        }

        /* Responsive logo sizing */
        .logo-img {
            width: 250px;
            max-width: 80vw;
            height: auto;
            /* Use the CSS variable based on system mode */
            filter: var(--logo-filter);
            transition: filter 0.5s ease;
        }

        @media (min-width: 768px) {
            .logo-img {
                width: 350px;
            }
        }

        /* Bottom Action Area Animation */
        .reveal-actions {
            opacity: 0;
            animation: slideUpFade 1.5s ease-out forwards;
            animation-delay: 4.5s;
            display: flex;
            flex-direction: column;
            gap: 1.5rem;
            align-items: center;
        }

        @keyframes slideUpFade {
            0% { opacity: 0; transform: translateY(20px); }
            100% { opacity: 1; transform: translateY(0); }
        }

